package com.superiorsoftllc.infantry.daemon

import java.security.SecureRandom

/**
 * SANDBOX-1 (ticket d4c1dbd9): who a caller is. With `limits.sandbox.mode` on, agents receive a SCOPED token generated by
 * the daemon at start (in memory only, never written to disk) instead of the owner token: [AccessTier.AGENT]. QA 950f4251
 * found the owner token in every agent's environment; an agent holding it could change settings, point a CLI location at
 * any binary, install harnesses or spawn sessions, i.e. leave the sandbox through the daemon.
 */
enum class AccessTier { OWNER, AGENT }

object AgentFrames {
    /**
     * What an agent-tier connection may send: reads, its own mail, its own progress/background-job/to-do reports, owner
     * questions, its ticket and knowledge bookkeeping. NOT: settings, CLI locations, harness installs, roles/agents/
     * traits/skills/prompts edits, tool approval, secrets, projects, commands/runs, triggers, spawns (`new`, pods),
     * prompting or killing other sessions.
     */
    val ALLOWED: Set<String> = setOf(
        "replay_request", "mail_send", "mail_read", "mail_inbox", "mail_outbox", "mail_thread", "mail_threads", "mail_waiting",
        "progress", "waiting", "bg_job", "question_ask", "question_cancel", "question_list", "prompt_ask",
        "ticket_get", "ticket_list", "ticket_move", "ticket_unassign", "agent_queue", "ticket_save", "ticket_link", "ticket_unlink",
        "memory_search", "memory_list", "memory_get", "memory_save", "decision_list", "decision_get", "decision_add",
        "issue_list", "issue_get", "issue_open", "issue_attempt", "issue_fix", "issue_precheck",
        "providers", "models", "settings_get", "limit_catalog", "limits", "usage_get", "role_list", "role_binding_list",
        "role_binding_get", "skill_list", "skill_get", "layer_skill_list", "trait_list", "trait_get", "role_traits_get", "role_traits_list",
        "pod_query", "agent_list", "agent_roster", "session_stats_get", "attention_list", "project_get", "project_list",
        "epic_list", "story_get", "story_list", "pipeline_show", "command_list", "prompt_list", "prompt_get",
    )

    fun allows(type: String): Boolean = type in ALLOWED

    fun refusal(type: String): String =
        "sandbox: '$type' is not available to a sandboxed agent (agent token: mail, board, status and reports only)"

    /** HTTP routes the agent token may call: health, the WebSocket and the agent mail API. */
    fun allowsHttp(method: String, path: String): Boolean =
        path == OPEN_PATH || path == AccessPolicy.BROWSER_PATH || path.startsWith("/mail/") || (method == "GET" && path == "/attention")

    /** A fresh scoped token: 32 random bytes, hex. */
    fun newToken(random: SecureRandom = SecureRandom()): String =
        ByteArray(32).also(random::nextBytes).joinToString("") { "%02x".format(it) }
}
